"""Regenerate VOID avatar assets at build time (binaries; this file is text-safe)."""
import base64, pathlib
ASSETS = {
    "idle.mp4": "",
    "working.mp4": "",
    "making.mp4": "",
    "celebrating.mp4": "",
    "poster.webp": "",
}

def main():
    d = pathlib.Path(__file__).resolve().parents[1] / 'app' / 'public' / 'avatar' / 'void'
    d.mkdir(parents=True, exist_ok=True)
    for name, b64 in ASSETS.items():
        (d / name).write_bytes(base64.b64decode(b64))
    print(f'avatar assets written to {d}')

if __name__ == "__main__":
    main()